const fmt = (d) => d.toISOString().slice(0, 10);
const now = new Date();
const curEnd = new Date(now); curEnd.setUTCDate(curEnd.getUTCDate() - 1);
const curStart = new Date(curEnd); curStart.setUTCDate(curStart.getUTCDate() - 27);
const prevEnd = new Date(curStart); prevEnd.setUTCDate(prevEnd.getUTCDate() - 1);
const prevStart = new Date(prevEnd); prevStart.setUTCDate(prevStart.getUTCDate() - 27);
return [{ json: { windows: { cur_start: fmt(curStart), cur_end: fmt(curEnd), prev_start: fmt(prevStart), prev_end: fmt(prevEnd), window_days: 28 } } }];

const rows = (items[0].json && items[0].json.rows) || [];
const ga4_rows = rows.map(r => ({
  path: (r.dimensionValues && r.dimensionValues[0] && r.dimensionValues[0].value) || '/',
  sessions: Number((r.metricValues && r.metricValues[0] && r.metricValues[0].value) || 0),
  conversions: Number((r.metricValues && r.metricValues[1] && r.metricValues[1].value) || 0)
}));
return [{ json: { ga4_rows } }];

const raw = items[0].json.data || '';
const locs = [...raw.matchAll(/<loc>\s*([^<\s]+)\s*<\/loc>/gi)].map(m => m[1]);
const isIndex = /<sitemapindex/i.test(raw);
const sitemap_urls = [...new Set(locs)].slice(0, 500);
if (!isIndex && sitemap_urls.length === 0) { throw new Error('Sitemap returned no URLs. Check ' + $('Run Config').first().json.site_url + 'sitemap.xml'); }
return [{ json: { sitemap_urls, sitemap_count: sitemap_urls.length, is_sitemap_index: isIndex } }];

const rowsOf = (node) => $(node).all().map(i => i.json).filter(Boolean);
const mapQ = (list) => list.flatMap(r => r.rows || []).map(r => ({ query: r.keys[0], clicks: r.clicks || 0, impressions: r.impressions || 0, ctr: r.ctr || 0, position: r.position || 100 }));
const mapP = (list) => list.flatMap(r => r.rows || []).map(r => ({ url: r.keys[0], clicks: r.clicks || 0, impressions: r.impressions || 0, position: r.position || 100 }));
const qCur = mapQ(rowsOf('GSC Current Queries'));
const qPrev = mapQ(rowsOf('GSC Previous Queries'));
const pCur = mapP(rowsOf('GSC Current Pages'));
const pPrev = mapP(rowsOf('GSC Previous Pages'));
const qp = rowsOf('GSC Query Page Rows').flatMap(r => r.rows || []).map(r => ({ query: r.keys[0], url: r.keys[1], clicks: r.clicks || 0, impressions: r.impressions || 0 }));
const sitemap = rowsOf('Parse Sitemap URLs')[0] || { sitemap_urls: [] };
let ga4Rows = [];
try { ga4Rows = $('GA4 Sessions Parsed').first().json.ga4_rows || []; } catch (e) { ga4Rows = []; }
const agentId = $('Validate SEO Agent').first().json.id;
const runId = $('Create Agent Run').first().json.id;
const W = $('Compute Windows').first().json.windows;

const expectedCtr = (p) => {
  const curve = [[1, 0.28], [2, 0.15], [3, 0.10], [4, 0.07], [5, 0.05], [6, 0.04], [7, 0.03], [8, 0.025], [9, 0.02], [10, 0.015]];
  for (const [pos, ctr] of curve) { if (p <= pos) return ctr; }
  if (p <= 20) return 0.008;
  if (p <= 30) return 0.004;
  return 0.002;
};

const prevQMap = new Map(qPrev.map(r => [r.query, r]));
const prevPMap = new Map(pPrev.map(r => [r.url, r]));
const bestPageFor = (query) => {
  const pages = qp.filter(x => x.query === query).sort((a, b) => b.impressions - a.impressions);
  return pages[0] ? pages[0].url : null;
};

// CTR opportunities: strong visibility, weak click-through vs position benchmark.
const ctrOpps = qCur
  .filter(r => r.impressions >= 100 && r.position <= 12 && (r.clicks / Math.max(1, r.impressions)) < expectedCtr(r.position) * 0.65)
  .map(r => ({ ...r, expected_ctr: expectedCtr(r.position), actual_ctr: r.clicks / Math.max(1, r.impressions) }))
  .sort((a, b) => b.impressions - a.impressions).slice(0, 8);

// Striking distance: page 2 / top-20 rankings worth pushing.
const rankOpps = qCur
  .filter(r => r.impressions >= 50 && r.position > 4 && r.position <= 20)
  .sort((a, b) => a.position - b.position).slice(0, 8);

// Declining pages: meaningful clicks lost vs previous window.
const declining = pCur
  .map(r => {
    const prev = prevPMap.get(r.url);
    return prev && prev.clicks >= 20 && r.clicks < prev.clicks * 0.8
      ? { url: r.url, cur_clicks: r.clicks, prev_clicks: prev.clicks, cur_position: r.position, prev_position: prev.position }
      : null;
  })
  .filter(Boolean)
  .sort((a, b) => (b.prev_clicks - b.cur_clicks) - (a.prev_clicks - a.cur_clicks)).slice(0, 8);

// Emerging queries: new demand or large position gains.
const emerging = qCur
  .filter(r => r.clicks >= 5)
  .map(r => {
    const prev = prevQMap.get(r.query);
    const improved = prev ? prev.position - r.position : 0;
    const isNew = !prev || prev.clicks === 0;
    return isNew || improved >= 10
      ? { query: r.query, clicks: r.clicks, impressions: r.impressions, position: r.position, previous_position: prev ? prev.position : null }
      : null;
  })
  .filter(Boolean).slice(0, 10);

// Cannibalization: same query served by multiple pages.
const byQuery = new Map();
for (const row of qp) {
  if (row.impressions >= 20) {
    if (!byQuery.has(row.query)) byQuery.set(row.query, new Map());
    byQuery.get(row.query).set(row.url, row);
  }
}
const cannibalization = [];
for (const [query, pages] of byQuery) {
  if (pages.size >= 2) {
    cannibalization.push({ query, pages: [...pages.values()].map(p => ({ url: p.url, impressions: p.impressions, clicks: p.clicks })) });
  }
  if (cannibalization.length >= 5) break;
}

// Pages in sitemap with zero current search visibility.
const seenPages = new Set(pCur.filter(r => r.impressions > 0).map(r => r.url.replace(/\/$/, '')));
const zeroVisibility = (sitemap.sitemap_urls || []).filter(u => !seenPages.has(u.replace(/\/$/, ''))).slice(0, 10);

// Keyword memory upserts.
const kwMap = new Map();
const addKw = (r, tag) => {
  if (!r || !r.query) return;
  const cur = kwMap.get(r.query) || { keyword: r.query, opportunity_score: 0, metrics: { window: '28d', signals: [], impressions: 0, clicks: 0, position: null } };
  cur.metrics.impressions = Math.max(cur.metrics.impressions, r.impressions || 0);
  cur.metrics.clicks = Math.max(cur.metrics.clicks, r.clicks || 0);
  cur.metrics.position = r.position || cur.metrics.position;
  if (!cur.metrics.signals.includes(tag)) cur.metrics.signals.push(tag);
  kwMap.set(r.query, cur);
};
ctrOpps.forEach(r => addKw(r, 'ctr_opportunity'));
rankOpps.forEach(r => addKw(r, 'striking_distance'));
emerging.forEach(r => addKw(r, 'emerging'));
const keyword_upserts = [...kwMap.values()].map(k => {
  const imp = k.metrics.impressions;
  const pos = k.metrics.position || 100;
  k.opportunity_score = Math.max(5, Math.min(100, Math.round((imp >= 500 ? 35 : imp >= 100 ? 25 : 10) + (pos <= 10 ? 35 : pos <= 20 ? 25 : 10) + k.metrics.signals.length * 10)));
  return k;
});

// Page memory upserts with GA4 enrichment.
const ga4ByPath = new Map(ga4Rows.map(g => [g.path.replace(/\/$/, ''), g]));
const page_upserts = pCur
  .filter(r => r.impressions > 0)
  .sort((a, b) => b.clicks - a.clicks).slice(0, 100)
  .map(r => {
    const path = r.url.replace(/^https?:\/\/[^/]+/, '').replace(/\/$/, '');
    const ga = ga4ByPath.get(path);
    return { url: r.url, metrics: { window: '28d', clicks: r.clicks, impressions: r.impressions, avg_position: r.position, ga4_sessions: ga ? ga.sessions : null, ga4_conversions: ga ? ga.conversions : null } };
  });

// Daily SEO task list.
const tasks = [];
const mk = (task_type, priority, title, description, payload) => tasks.push({
  created_by_agent: agentId, task_type, title, description, priority,
  confidence: 0.7, expected_impact: payload.expected_impact || null,
  status: 'queued', requires_approval: false, payload
});
for (const r of ctrOpps) mk('seo_ctr_opportunity', 'P2',
  'Improve CTR: ' + r.query,
  'Query ranks at position ' + Number(r.position).toFixed(1) + ' with ' + r.impressions + ' impressions but CTR ' + (r.actual_ctr * 100).toFixed(1) + '% is below the ' + (r.expected_ctr * 100).toFixed(1) + '% benchmark for this position. Rewrite title/meta on the ranking page to match intent.',
  { query: r.query, url: bestPageFor(r.query), impressions: r.impressions, actual_ctr: r.actual_ctr, expected_ctr: r.expected_ctr, expected_impact: 'recover ' + Math.round(r.impressions * (r.expected_ctr - r.actual_ctr)) + ' clicks/28d' });
for (const r of rankOpps) mk('seo_ranking_opportunity', 'P2',
  'Push striking-distance query: ' + r.query,
  'Query sits at position ' + Number(r.position).toFixed(1) + ' with ' + r.impressions + ' impressions. Add depth, internal links, and entity coverage to reach page one.',
  { query: r.query, url: bestPageFor(r.query), impressions: r.impressions, position: r.position, expected_impact: 'page-one ranking potential' });
for (const d of declining) mk('seo_declining_page', 'P1',
  'Investigate declining page: ' + d.url,
  'Clicks fell from ' + d.prev_clicks + ' to ' + d.cur_clicks + ' vs the previous 28 days (avg position ' + Number(d.prev_position).toFixed(1) + ' to ' + Number(d.cur_position).toFixed(1) + '). Check SERP changes, content freshness, and technical issues.',
  { url: d.url, cur_clicks: d.cur_clicks, prev_clicks: d.prev_clicks, expected_impact: 'recover lost clicks' });
for (const r of emerging) mk('seo_emerging_query', 'P3',
  'Emerging query: ' + r.query,
  'Query gained traction (' + r.clicks + ' clicks, position ' + Number(r.position).toFixed(1) + (r.previous_position ? ', up from ' + Number(r.previous_position).toFixed(1) : '') + '). Evaluate a dedicated section or article.',
  { query: r.query, clicks: r.clicks, impressions: r.impressions, position: r.position, expected_impact: 'ride growing demand' });
for (const c of cannibalization) mk('seo_cannibalization', 'P2',
  'Resolve cannibalization: ' + c.query,
  'Query is served by ' + c.pages.length + ' competing URLs (' + c.pages.map(p => p.url).join(', ') + '). Consolidate, differentiate intents, or canonicalize.',
  { query: c.query, pages: c.pages, expected_impact: 'consolidate ranking signals' });
for (const u of zeroVisibility) mk('seo_zero_visibility', 'P3',
  'No search visibility: ' + u,
  'Page is in the sitemap but earned zero impressions in the current 28-day window. Confirm indexation, intent, and internal linking.',
  { url: u, expected_impact: 'indexation hygiene' });

return [{ json: {
  agent_id: agentId,
  agent_run_id: runId,
  site_url: $('Run Config').first().json.site_url,
  windows: W,
  summary: {
    ctr_opportunities: ctrOpps.length,
    ranking_opportunities: rankOpps.length,
    declining_pages: declining.length,
    emerging_queries: emerging.length,
    cannibalization_queries: cannibalization.length,
    zero_visibility_pages: zeroVisibility.length,
    keywords_upserted: keyword_upserts.length,
    pages_upserted: page_upserts.length,
    tasks_created: tasks.length
  },
  keyword_upserts,
  page_upserts,
  tasks
} }];
